static bool scrambleCheck(const char *s1, const char *s2, int len) {
  if (len == 1) return s1[0] == s2[0];

  int cnt[26] = {0};
  for (int i = 0; i < len; i++) {
    cnt[s1[i] - 'a']++;
    cnt[s2[i] - 'a']--;
  }
  for (int i = 0; i < 26; i++) {
    if (cnt[i]) return false;
  }

  for (int i = 1; i < len; i++) {
    if ((scrambleCheck(s1, s2, i) && scrambleCheck(s1 + i, s2 + i, len - i)) ||
        (scrambleCheck(s1, s2 + len - i, i) && scrambleCheck(s1 + i, s2, len - i))) {
      return true;
    }
  }
  return false;
}

bool isScramble(char *s1, char *s2) {
  int n = strlen(s1);
  if (n != (int)strlen(s2)) return false;
  return scrambleCheck(s1, s2, n);
}

class Solution {
  bool check(const string &s1, const string &s2) {
    if (s1 == s2) return true;
    if (s1.size() == 1) return false;

    int cnt[26] = {0};
    for (char c : s1) cnt[c - 'a']++;
    for (char c : s2) cnt[c - 'a']--;
    for (int i = 0; i < 26; i++) {
      if (cnt[i]) return false;
    }

    int n = s1.size();
    for (int i = 1; i < n; i++) {
      if ((check(s1.substr(0, i), s2.substr(0, i)) && check(s1.substr(i), s2.substr(i))) ||
          (check(s1.substr(0, i), s2.substr(n - i)) && check(s1.substr(i), s2.substr(0, n - i)))) {
        return true;
      }
    }
    return false;
  }

public:
  bool isScramble(string s1, string s2) {
    return check(s1, s2);
  }
};

