impl Solution {
  pub fn is_scramble(s1: String, s2: String) -> bool {
    fn check(a: &[u8], b: &[u8]) -> bool {
      if a == b {
        return true;
      }
      if a.len() == 1 {
        return false;
      }
      let mut cnt = [0i32; 26];
      for i in 0..a.len() {
        cnt[(a[i] - b'a') as usize] += 1;
        cnt[(b[i] - b'a') as usize] -= 1;
      }
      if cnt.iter().any(|&c| c != 0) {
        return false;
      }
      let n = a.len();
      for i in 1..n {
        if (check(&a[..i], &b[..i]) && check(&a[i..], &b[i..]))
          || (check(&a[..i], &b[n - i..]) && check(&a[i..], &b[..n - i]))
        {
          return true;
        }
      }
      false
    }
    check(s1.as_bytes(), s2.as_bytes())
  }
}

const isScramble = (s1: string, s2: string): boolean => {
  const check = (a: string, b: string): boolean => {
    if (a === b) return true;
    if (a.length === 1) return false;
    const cnt = new Array(26).fill(0);
    for (let i = 0; i < a.length; i++) {
      cnt[a.charCodeAt(i) - 97]++;
      cnt[b.charCodeAt(i) - 97]--;
    }
    if (cnt.some((c) => c !== 0)) return false;
    const n = a.length;
    for (let i = 1; i < n; i++) {
      if (
        (check(a.slice(0, i), b.slice(0, i)) && check(a.slice(i), b.slice(i))) ||
        (check(a.slice(0, i), b.slice(n - i)) && check(a.slice(i), b.slice(0, n - i)))
      ) {
        return true;
      }
    }
    return false;
  };
  return check(s1, s2);
};
